+          tagAge: const Duration(hours: 2),
+          runsJson: '[]',
+          secondReadJson: '[]',
+          thirdReadJson:
+              '[{"databaseId":4242,"status":"queued","conclusion":null,"event":"push"}]',
+          rearmPushTo: 'origin',
