#!/usr/bin/env bash
echo "$*" >> "$GH_LOG_FILE"
cmd="$1"; shift || true
case "$cmd" in
  run)
    sub="$1"; shift || true
    case "$sub" in
      list)
        branch=""; jqf="."
        while [ $# -gt 0 ]; do
          case "$1" in
            --branch) branch="$2"; shift 2 ;;
            --jq) jqf="$2"; shift 2 ;;
            *) shift ;;
          esac
